/** Locale BCP47 untuk format tanggal/waktu per kode bahasa SUKI. */
const LOCALE_BY_LANGUAGE: Record<string, string> = {
  id: 'id-ID', en: 'en-US', ms: 'ms-MY', jv: 'jv-ID', su: 'su-ID',
  zh: 'zh-CN', ja: 'ja-JP', ko: 'ko-KR', th: 'th-TH', vi: 'vi-VN',
  tl: 'fil-PH', hi: 'hi-IN', bn: 'bn-BD', ur: 'ur-PK', ta: 'ta-IN',
  my: 'my-MM', km: 'km-KH', ar: 'ar-SA', fa: 'fa-IR', tr: 'tr-TR',
  es: 'es-ES', fr: 'fr-FR', de: 'de-DE', pt: 'pt-PT', it: 'it-IT',
  nl: 'nl-NL', ru: 'ru-RU',
};

/** Kembalikan locale Intl.DateTimeFormat yang tepat untuk kode bahasa SUKI. */
export function timeLocale(language: string): string {
  return LOCALE_BY_LANGUAGE[language] || 'id-ID';
}
